contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _am, uint _collectAm) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (_am)); require(_am <= 1000000000000000000000000000000);
        require(address(this).balance >= _am);
        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        uint beforeDeposit = c.balances(address(this)); if (__ESBMC_reverted()) return;
        c.Deposit{value: _am}(); if (__ESBMC_reverted()) return;
        uint afterDeposit = c.balances(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.Collect(_collectAm); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint afterCollect = c.balances(address(this)); if (__ESBMC_reverted()) return;

        bool noUnderflow = afterDeposit >= beforeDeposit;
        bool depositExact = afterDeposit == beforeDeposit + _am;
        bool revertPreserves = !reverted || afterCollect == afterDeposit;
        assert(noUnderflow && depositExact && revertPreserves);
    }

    receive() external payable {}
}

