pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 _am, uint256 _collectAm) internal {
        _am = bound(_am, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= _am);
        try c.SetMinSum(0) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 beforeDeposit;
        try c.balances(address(this)) returns (uint256 __r) { beforeDeposit = __r; } catch { return; }
        try c.Deposit{value: _am}() {} catch { return; }
        uint256 afterDeposit;
        try c.balances(address(this)) returns (uint256 __r) { afterDeposit = __r; } catch { return; }
        bool reverted;
        try c.Collect(_collectAm) { reverted = false; } catch { reverted = true; }
        uint256 afterCollect;
        try c.balances(address(this)) returns (uint256 __r) { afterCollect = __r; } catch { return; }
        bool noUnderflow = afterDeposit >= beforeDeposit;
        bool depositExact = afterDeposit == beforeDeposit + _am;
        bool revertPreserves = !reverted || afterCollect == afterDeposit;
        assertTrue(noUnderflow && depositExact && revertPreserves);
    }

    function testFuzz_run(uint256 _am, uint256 _collectAm) public {
        _run(_am, _collectAm);
    }

    receive() external payable {}
}
